(* [comment removed for export] *)
Lemma fs_scratch_pop : forall (H : asr) f LF iv, fs_scratch H (f :: LF) iv -> fs_scratch H LF iv.
Proof.
  intros H f LF iv [E|(k & ff & fp & FF & E)]; [left; exact E| right].
  exists k, ff, fp. split; [| exact E]. destruct FF as (A & B & C). split; [exact A|]. split; [exact B|].
  intros g IN. apply C. right. exact IN.
Qed.
Lemma Forall_scratch_pop : forall (H : asr) f LF XS, Forall (fs_scratch H (f :: LF)) XS -> Forall (fs_scratch H LF) XS.
Proof. intros H f LF XS FX. eapply Forall_impl; [| exact FX]. intros iv K. eapply fs_scratch_pop. exact K. Qed.

(* [comment removed for export] *)
Lemma otf_name_acc : forall m ff (z2 : list byte), 0 <= ff -> ff mod 8 = 0 -> ff + 48 <= AAPP_HI ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450884) [CB 2 z2] -> z2 = repeat (b8 0) 2 ->
  accessible m (ff + 32) 16.
