Lemma rw_cells_CB0_intro : forall m A, 0 <= A <= 2^64 -> rw_cells bsegs m A [CB 0 []].
Proof.
  intros m A HA. split; [split|].
  - cbn. split; [reflexivity| exact I].
  - split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
  - split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
Qed.

Section SA.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis FS0 : stack_malloc_stmt H 0 P_A_FS_MALLOC_0.
  (* [comment removed for export] *)
  Hypothesis EXISTS : token_list_exists_stmt H.

Definition OTF_SEGA_STACK : Z := 176 + AEXISTS_STACK.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition otf_live (m' : mem) (sp : word) (spa lo : Z) (gsz : nat) (j16 gj fj sh8 : list byte) (h0 h1 h2 h3 : word)
    (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (np nl vl ecA ff fp tlp tll : Z) : Prop :=
  spa + 56 + Z.of_nat gsz = bv_unsigned sp + -104 /\ bv_unsigned sp - 176 <= spa /\ spa mod 32 = 0
  /\ rw_cells bsegs m' spa (otf_locals j16 vl ecA ff tlp tll)
  /\ rw_cells bsegs m' (spa + 56) [CB gsz gj]
  /\ rw_cells bsegs m' (bv_unsigned sp + -104) (otf_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
  /\ rw_cells bsegs m' ff [C8 h0; C8 h1; C8 h2; C8 h3]
  /\ rw_cells bsegs m' (ff + 32) [C8 (wz np); C8 (wz nl)]
  /\ rw_cells bsegs m' (ff + 48) [CB 8 fj; C8 (wz fp)]
  /\ rw_cells bsegs m' (Z.shiftr ff 3 + 2147450880) [CB 8 sh8]
  /\ rw_cells bsegs m' fp [C1 (b8 1)]
  /\ stk bsegs m' lo spa.

Definition otf_segA_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s : as_St H) (LB : list block) (LF : list fframe)
    (P f np vp ecA : Z) (name value : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo shi : Z) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists (kept : bool) rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s4x t3 t4 t5 t6 m' (ff fp spa : Z) (gsz : nat)
                    (j16 gj fj sh8 : list byte) (h0 h1 h2 h3 : word) (tlp tll : Z) XS,
    munch ((lo, bv_unsigned sp) :: XS)%Z m m' /\ Forall (fs_scratch H LF) XS /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ AFieldsC m' (P + 80) S L ns ls em /\ FT m'
    /\ as_RHEAP H s LB m' /\ as_RFS H ((0, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi
    /\ otf_live m' sp spa lo gsz j16 gj fj sh8 h0 h1 h2 h3 ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 np (zlength name) (zlength value) ecA ff fp tlp tll
    /\ (forall a, rin_ivs (otf_retW ff fp) a -> rin_ivs XS a)          (* [comment removed for export] *)
    /\ ms' = MS (mkR (if kept then Z_to_bv 64 P_A_OTF_RET else rax) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa)
                     (if kept then Z_to_bv 64 (P + 80) else a0) (if kept then Z_to_bv 64 f else a1)
                     (if kept then Z_to_bv 64 np else a2) (if kept then Z_to_bv 64 (zlength name) else a3)
                     (if kept then Z_to_bv 64 vp else a4) (if kept then Z_to_bv 64 (zlength value) else a5)
                     (if kept then Z_to_bv 64 ecA else a6) a7
                     (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) s4x (Z_to_bv 64 vp) (Z_to_bv 64 f) (Z_to_bv 64 P)
                     (Z_to_bv 64 (ff + 32)) (Z_to_bv 64 (P + 80)) (Z_to_bv 64 np) (Z_to_bv 64 ff) t3 t4 t5 t6)
                F (Z_to_bv 64 (if kept then P_A_FIELDS_INSERT else P_A_OTF_RET)) fc None m' (seg_rom bsegs).

(* [comment removed for export] *)
Definition otf_segA_stmt : Prop := forall (s : as_St H) (LB : list block) (LF : list fframe)
    (P f np vp ecA : Z) (mb : byte) (name value : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo shi : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  AFieldsC m (P + 80) S L ns ls em -> AFieldsOwn LB em -> FT m -> rw_cells bsegs m (P + 242) [C1 mb] ->
  bytes_at bsegs m np name -> np + zlength name < 2^64 ->
  0 <= f < 2^64 -> 0 <= vp < 2^64 -> zlength value < 2^64 -> 0 <= ecA < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + OTF_SEGA_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m ->
  as_RHEAP H s LB m -> as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp <= shi ->
  0 <= P -> aobj LB LF (P + 80) 48 -> aobj LB LF (P + 242) 1 -> accessible m (P + 242) 1 ->
  aobj LB LF np (zlength name) -> accessible m np (zlength name) ->
  (* [comment removed for export] *)
  bv_unsigned mb <= 1 -> (length LF + 1 < AFS_MAXLIVE)%nat ->
  evt bsegs (otf_segA_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF P f np vp ecA name value S L ns ls em lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 P) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name))
              (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) (Z_to_bv 64 ecA) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_ON_TRAILER_FIELD_IMPL) fc None m (seg_rom bsegs)).

